for (const item of $input.all()) {
  let raw = item.json.review_text || '';

  let cleaned = raw.replace(/<[^>]*>/g, ' ');
  cleaned = cleaned.replace(/&quot;/g, '"')
                   .replace(/&amp;/g, '&')
                   .replace(/&#39;/g, "'")
                   .replace(/&lt;/g, '<')
                   .replace(/&gt;/g, '>');
  cleaned = cleaned.replace(/\s+/g, ' ').trim();

  item.json.cleaned_text = cleaned;
  item.json.raw_text = raw;
  item.json.product_name = item.json.product_name || 'UNKNOWN_PRODUCT';
  item.json.rating = parseInt(item.json.rating) || 3;
}
return $input.all();

const response = $input.first().json;
let label = 'NEUTRAL';
let score = 0.5;

try {
  const scores = Array.isArray(response) ? (Array.isArray(response[0]) ? response[0] : response) : [];
  if (scores.length > 0) {
    const top = scores.reduce((prev, curr) => (curr.score > prev.score ? curr : prev), scores[0]);
    label = top.label || 'UNKNOWN';
    score = parseFloat(top.score || 0.5);
  }
} catch (err) {
  label = 'UNKNOWN';
  score = 0.5;
}

return [{
  json: {
    raw_review_id: $('Save Raw to Postgres').first().json.id,
    product_name: $('Clean Text (Regex)').first().json.product_name,
    cleaned_text: $('Clean Text (Regex)').first().json.cleaned_text,
    sentiment_label: label,
    sentiment_confidence: score,
    needs_review: score < 0.60
  }
}];

