const prev = $('Parse Sentiment & Confidence').first().json;
const groqRes = $input.first().json;

let topics = [];
let complaint = null;
let summary = '';
let parseError = false;

try {
  const content = groqRes.choices[0].message.content;
  const parsed = JSON.parse(content);
  topics = Array.isArray(parsed.topics) ? parsed.topics : [];
  complaint = parsed.complaint || null;
  summary = parsed.summary || '';
} catch (err) {
  parseError = true;
  topics = ['general_review'];
  complaint = 'Extraction note: review details checked';
  summary = prev.cleaned_text.slice(0, 100) + '...';
}

return [{
  json: {
    raw_review_id: prev.raw_review_id,
    product_name: prev.product_name,
    sentiment_label: prev.sentiment_label,
    sentiment_confidence: prev.sentiment_confidence,
    needs_review: prev.needs_review || parseError,
    topics: JSON.stringify(topics),
    complaint_summary: complaint,
    review_summary: summary
  }
}];
